def check_discriminant(b):
    # D = (2^(b+1) - 1)^2 - 8 * 3^b
    N_b = (2**(b+1) - 1)
    D = N_b**2 - 8 * (3**b)

    if D < 0:
        return None, "Negative D"

    k = int(D**0.5)
    if k*k == D:
        return k, "Perfect Square"
    else:
        return None, "Not a perfect square"

test_b = [7, 8, 9, 10]
results = {}
for b in test_b:
    k, status = check_discriminant(b)
    results[b] = (k, status)

print(results)
